// Original AS91526 theory revision content. Prepared, not yet registered in the
// live Mechanics bank: Electricity remains sealed until its journey is built.
// Levels describe reasoning demand, NOT awarded NZQA grades.
// Full explanations are separate from choices to avoid rewarding verbosity.
// Ideal components, sinusoidal steady-state AC, and negligible wire resistance
// are assumed unless a prompt explicitly specifies otherwise.
const ELECTRICITY_SOURCES = {
  standard: 'https://www.nzqa.govt.nz/nqfdocs/ncea-resource/achievements/2023/as91526.pdf',
  specification: 'https://www.nzqa.govt.nz/nqfdocs/ncea-resource/specifications/2026/91523-spc-2026.pdf',
  schedule2025: 'https://www.nzqa.govt.nz/nqfdocs/ncea-resource/schedules/2025/91526-ass-2025.pdf',
  schedule2024: 'https://www.nzqa.govt.nz/nqfdocs/ncea-resource/schedules/2024/91526-ass-2024.pdf',
  report2024: 'https://www.nzqa.govt.nz/nqfdocs/ncea-resource/reports/2024/91526-report-2024.pdf',
  capacitance: 'https://openstax.org/books/university-physics-volume-2/pages/8-1-capacitors-and-capacitance',
  dielectric: 'https://openstax.org/books/university-physics-volume-2/pages/8-5-molecular-model-of-a-dielectric',
  faraday: 'https://openstax.org/books/university-physics-volume-2/pages/13-1-faradays-law',
  lenz: 'https://openstax.org/books/university-physics-volume-2/pages/13-2-lenzs-law',
  transformers: 'https://openstax.org/books/university-physics-volume-2/pages/15-6-transformers',
  rl: 'https://openstax.org/books/university-physics-volume-2/pages/14-4-rl-circuits',
  lc: 'https://openstax.org/books/university-physics-volume-2/pages/14-5-oscillations-in-an-lc-circuit',
  ac: 'https://openstax.org/books/university-physics-volume-2/pages/15-2-simple-ac-circuits',
  phasors: 'https://openstax.org/books/university-physics-volume-2/pages/15-3-rlc-series-circuits-with-ac',
  resonance: 'https://openstax.org/books/university-physics-volume-2/pages/15-5-resonance-in-an-ac-circuit'
};

function electricitySection(topic, act, sources, rows) {
  return rows.map(([suffix, level, strands, q, answers, correct, explanation]) => ({
    id: `elec-${topic}-${suffix}`, journey: 'electricity', standard: '91526',
    topic, act, level, theory: true, strands, strand: strands[0],
    q, answers, correct, explanation,
    sourceIds: ['standard', 'specification', 'report2024', ...sources]
  }));
}

